import {screens,byId,roles,groups} from './catalog.js';
import {adminMenu,adminLogin,adminDashboard} from './admin.js';
import {load,save,seed,label,TODAY,KEY,DISTRICTS} from './store.js';
import {maskName,weekRange,upsert,streak,scopeMembers,attendanceMetric,reportSnapshot,carryActions} from './domain.js';
import {workbook} from './export.js';
const $=s=>document.querySelector(s);
const params=new URLSearchParams(location.search);
let state=load(),role=params.get('role')||sessionStorage.getItem('demo-role')||'district',district=sessionStorage.getItem('demo-district')||'1구역',week=41,service='주일',memberId='m1',tab='기본정보',route='',month='2026-10',kind='회비',search='',statusFilter='활동',stageFilter='',courseId='cr1',session=8,examId='ex1';
if(!roles[role])role='district';
if(!DISTRICTS.includes(district))district='1구역';
if(role!=='district')district='전체 구역';
document.body.classList.toggle('wireframe',params.get('wireframe')==='1');
const paths={home:'M3 10 12 3l9 7v11H3Z M9 21v-8h6v8',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 7 M22 21v-2a4 4 0 0 0-3-4',sprout:'M12 21v-9 M12 16C3 16 3 9 3 7c8 0 9 4 9 9 M12 12c0-6 3-9 9-9 0 6-3 9-9 9',check:'M9 11l3 3 7-8 M21 12v8H3V4h11',heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 1 9 8 15 7-6 12-11 8-15Z',book:'M12 21V5 M12 5C9 3 5 3 2 4v16c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1',wallet:'M3 5h17v15H3Z M3 8h19v9h-7V8 M18 12h1',file:'M14 2H4v20h16V8Z M14 2v6h6 M8 12h8 M8 16h8',message:'M3 3h18v14H8l-5 4Z M7 7h10 M7 11h7',network:'M8 2h8v6H8Z M2 16h6v6H2Z M16 16h6v6h-6Z M12 8v5 M5 16v-3h14v3',shield:'M12 2 3 6v6c0 5 4 8 9 10 5-2 9-5 9-10V6Z M8 12l3 3 5-6',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',down:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',menu:'M3 6h18 M3 12h18 M3 18h18',x:'M6 6l12 12 M18 6 6 18',clock:'M12 8v4l3 2 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',lock:'M5 11h14v10H5Z M8 11V7a4 4 0 0 1 8 0v4',edit:'m14 5 5 5 M3 21l5-1L21 7l-4-4L4 16Z'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allowed=id=>byId[id]?.allow.includes(role);
const members=()=>scopeMembers(state,role,district).filter(m=>district==='전체 구역'||m.district===district);
const visibleIds=()=>new Set(members().map(m=>m.id));
const scoped=(list,key='memberId')=>list.filter(r=>visibleIds().has(r[key]));
const canWriteFinance=()=>role==='finance';
const canViewFinance=()=>['finance','lead'].includes(role);
const sensitive=r=>role==='lead'||(r.author===role&&(role!=='district'||r.district===district||state.members.find(m=>m.id===r.memberId)?.district===district));
const named=id=>esc(label(state,id));
const badge=(text)=>`<span class="badge ${['결석','미납','중단','기한 경과'].includes(text)?'red':['장기결석','요청','작성중','미입력','진행','권한 회수 대기'].includes(text)?'warn':['미제출','비활성','미응시'].includes(text)?'neutral':''}">${esc(text)}</span>`;
const btn=(text,action,primary=false,extra='')=>`<button type="button" class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${esc(text)}</button>`;
const link=(text,id,primary=false)=>allowed(id)?`<a class="btn ${primary?'primary':''}" href="#${id}">${esc(text)}</a>`:'';
const panel=(title,body,more='',desc='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${more}</div><div class="panel-body">${body}</div></section>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}"><div class="empty">해당 조건의 기록이 없습니다.</div></td></tr>`}</tbody></table></div>`;
const option=(v,l,sel)=>`<option value="${esc(v)}" ${String(v)===String(sel)?'selected':''}>${esc(l??v)}</option>`;
const select=(name,list,value,attrs='')=>`<select name="${name}" ${attrs}>${list.map(x=>Array.isArray(x)?option(x[0],x[1],value):option(x,x,value)).join('')}</select>`;
const field=(name,title,type='text',value='',extra='')=>`<label class="field ${type==='textarea'?'full':''}"><span>${title}</span>${type==='textarea'?`<textarea name="${name}" ${extra}>${esc(value)}</textarea>`:`<input type="${type}" name="${name}" value="${esc(value)}" ${extra}>`}</label>`;
const sf=(name,title,list,value='',extra='')=>`<label class="field"><span>${title}</span>${select(name,list,value,extra)}</label>`;
const memberOpts=()=>members().map(m=>[m.id,label(state,m.id)]);
const prospectOpts=()=>state.prospects.filter(p=>visibleIds().has(p.guideId)).map(p=>[p.id,label(state,p.id)]);
const nf=(name,title,value='')=>sf(name,title,memberOpts(),value,'required');
const notice=(title,text,info=false)=>`<div class="notice ${info?'info':''}">${icon(info?'shield':'clock')}<div><strong>${title}</strong>${text}</div></div>`;
const stat=(title,value,hint='',accent=false,suffix='',ic='check')=>`<div class="stat ${accent?'accent':''}"><div class="stat-top">${title}${icon(ic)}</div><div class="stat-value">${value}<small>${suffix}</small></div><div class="stat-hint">${hint}</div></div>`;
const form=(id,body,text='저장',secondary='')=>`<form id="${id}"><div class="form-grid">${body}</div><div class="form-actions">${secondary}<button class="btn primary" type="submit">${text}</button></div></form>`;
const rowEdit=(collection,id,text='수정')=>btn(text,'edit-record',false,`data-collection="${collection}" data-id="${esc(id)}"`);
function audit(action,target,reason=''){state.audit.unshift({id:crypto.randomUUID(),at:new Date().toISOString(),role,action,target,reason});save(state)}
function persist(action,target){audit(action,target);save(state);toast('저장했습니다. 관련 현황에 반영되었습니다.');render()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function goto(id){location.hash=id}
function nameLink(m){return allowed('MB-03')?`<a class="name-link" href="#MB-03" data-member="${m.id}"><span class="avatar">${esc(m.name[0])}</span>${named(m.id)}</a>`:named(m.id)}
function scopeControls(){const range=weekRange(2026,week);return `<div class="scope-bar">${icon('clock')}${select('week',Array.from({length:12},(_,i)=>[30+i,`2026년 ${30+i}주차`]),week,'aria-label="주차" data-control="week"')}<span>${range.start.slice(5).replace('-','.')} - ${range.end.slice(5).replace('-','.')}</span>${role==='district'?`<span>담당 ${esc(district)}</span>`:select('scope',['전체 구역',...DISTRICTS],district==='전체 구역'?'전체 구역':district,'aria-label="조회 구역" data-control="scope"')}<span class="badge neutral">일요일 - 토요일</span></div>`}
function financeControls(){return `<div class="filter-row">${field('month','납부 연월','month',month,'data-control="month"')}${select('kind',['십일조','회비','서포터즈'],kind,'aria-label="납부 구분" data-control="kind"')}<span class="muted small-text">활동 회원 기준 / 회계 분리 영역</span></div>`}
function groupTabs(s){const pages=screens.filter(x=>x.group===s.group&&x.allow.includes(role)&&!['CM-01','AD-01'].includes(x.id));return pages.length>1?`<nav class="subtabs" aria-label="업무 하위 화면">${pages.map(p=>`<a href="#${p.id}" class="${p.id===s.id?'active':''}">${esc(p.title)}</a>`).join('')}</nav>`:''}
function navigation(s){const active=s.group;if(role==='admin')return '<div class="nav-label">ADMINISTRATION</div>'+adminMenu.map(([id,title,ic])=>`<a class="nav-item ${s.id===id?'active':''}" href="#${id}">${icon(ic)}${title}</a>`).join('');return groups.map(([id,title,ic],i)=>{const ps=screens.filter(p=>p.group===id&&!['CM-01','AD-01'].includes(p.id)&&p.allow.includes(role));if(!ps.length)return '';return `${id==='CM'?'<div class="nav-label">WORKSPACE</div>':id==='MB'?'<div class="nav-label">회원과 함께하는 업무</div>':id==='FN'?'<div class="nav-label">운영 및 보고</div>':id==='OR'?'<div class="nav-label">기준 및 시스템</div>':''}<a class="nav-item ${id===active?'active':''}" href="#${ps[0].id}">${icon(ic)}${title}<span class="nav-count">${ps.length}</span></a>`}).join('')}
function shell(s,body){const active=s.group;return `<div class="app-shell"><button class="menu-backdrop" data-action="menu-close" aria-label="메뉴 닫기" tabindex="-1" hidden></button><aside id="main-menu" class="sidebar" aria-label="주요 메뉴"><div class="drawer-head"><strong>주요 메뉴</strong><button class="icon-btn drawer-close" data-action="menu-close" aria-label="메뉴 닫기">${icon('x')}</button></div><a class="brand" href="#${role==='admin'?'AD-02':'CM-02'}"><span class="brand-mark"><img src="assets/logo.jpg" alt="신도림 로고"></span><div><strong>일심도림</strong></div></a><div class="region-label">신도림지역 · ${role==='admin'?'관리자 콘솔':'신앙관리 시스템'}</div>${navigation(s)}<div class="sidebar-foot"><div class="person"><span class="avatar">${role==='district'?'구':'담'}</span><div>${roles[role]}<br><small>${role==='district'?district:'신도림지역'}</small></div></div><a href="#CM-03">내 정보</a> · <a href="#${role==='admin'?'AD-01':'CM-01'}" data-action="logout">로그아웃</a></div></aside><main class="main"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="메뉴 열기" aria-controls="main-menu" aria-expanded="false">${icon('menu')}</button><span class="crumb">신도림지역 &nbsp; / &nbsp; ${groups.find(g=>g[0]===s.group)?.[1]}</span><div class="controls"><span class="small-text muted">시안 역할</span>${select('role',Object.entries(roles),role,'aria-label="시안 역할 전환" data-control="role"')}${role==='district'?select('district',DISTRICTS,district,'aria-label="시안 담당 구역" data-control="district"'):''}<button class="icon-btn" data-action="help" aria-label="시안 안내">${icon('shield')}</button><span class="avatar">${role==='admin'?'관':role==='lead'?'지':'구'}</span></div></header><div class="demo-banner"><span>화면설계 시안 · 모든 인명/연락처/업무 기록은 가상 데이터</span><a href="#SY-01" data-action="catalog">${screens.length}개 화면 목록</a></div><div class="content"><div class="page-head"><div><div class="eyebrow">${s.id} &nbsp; / &nbsp; SINDORIM WORKSPACE</div><h1>${s.title}</h1><p>${s.description}</p></div><div class="page-actions">${actionsFor(s)}</div></div>${groupTabs(s)}${body}<div class="footer-note"><span>이름 마스킹 · 역할과 소속 범위에 따른 시안 보기</span><span>${s.source?`기획서 p.${s.source}`:'추가 요청 / 관리자 화면'} · ${s.id} &nbsp; | &nbsp; 실제 운영에는 서버 인증 / RLS 필요</span></div></div></main></div>`}
function actionsFor(s){switch(s.type){case'members':return btn('마스킹 Excel','download-members')+link('회원 등록','MB-02',true);case'prospects':return link('대상자 등록','EV-02',true);case'visits':return link('심방 기록','VS-01',true);case'finance':return link('납부 등록','FN-01',true);case'unpaid':return btn('마스킹 Excel','download-unpaid');case'dashboard':return link('출석 입력','AT-01')+link('주간보고 작성','WR-01',true);default:return ''}}
function login(){return `<div class="login"><section class="login-story"><div class="login-brand"><img src="assets/logo.jpg" alt="신도림 로고"><div><strong>일심도림</strong></div></div><div class="eyebrow" style="color:#accab6">SINDORIM · FAITH & COMMUNITY</div><h1>한 사람의 기록을,<br>함께 이어갑니다.</h1><p>흩어진 기록을 한곳에 연결하고<br>이번 주 필요한 돌봄을 놓치지 않도록.</p><div class="login-line"></div><div class="small-text">회원 중심 통합 이력 &nbsp; / &nbsp; 주차별 업무 &nbsp; / &nbsp; 필요한 범위만</div></section><section class="login-form"><div class="login-box"><div class="eyebrow">CM-01 / 로그인</div><h2>업무를 시작하세요.</h2><p class="muted small-text">개인에게 부여된 계정으로 접속합니다.</p><form id="login-form">${field('email','이메일','email','district@example.test','required autocomplete="username"')}${field('password','비밀번호','password','demo1234','required autocomplete="current-password"')}<div class="login-options"><label><input type="checkbox" name="remember"> 세션 유지</label><button class="icon-btn small-text" type="button" data-action="reset-password">비밀번호 재설정</button></div>${sf('role','검토할 시안 역할',Object.entries(roles),role)}<button class="btn primary" type="submit">가상 계정으로 시작 ${icon('arrow')}</button></form><a class="btn admin-entry" href="#AD-01">${icon('shield')} 관리자 로그인</a>${notice('가상 데이터 시안','로그인 동작은 화면 검토용입니다. 실제 계정이나 개인정보를 입력하지 마세요.',true)}</div></section></div>`}
function dashboard(){const ms=members(),metric=attendanceMetric(state,ms,week,service);const abs=scoped(state.cases),pending=scoped(state.interviews).filter(i=>i.status==='요청'),vis=scoped(state.visits).filter(v=>v.status!=='완료'),pro=state.prospects.filter(p=>visibleIds().has(p.guideId));const lead=role==='lead';let cards;
 if(lead||role==='district')cards=stat(lead?'이번 주 출석률':'출석 미입력',lead?metric.rate:metric.missing,lead?`${metric.present} / ${metric.total}명 · 주일 기준`:'입력 후 주간보고 자동 반영',true,lead?'%':'명')+stat('장기결석 대상',abs.length,'시안 기준 8주 이상',false,'명','users')+stat(lead?'면담 요청 대기':'후속조치 진행',lead?pending.length:vis.length,'접수 및 기한 확인',false,'건','heart')+stat('주간보고',lead?state.reports.filter(r=>r.week===week).length:(state.reports.find(r=>r.week===week&&r.district===district)?.status||'작성중'),lead?'제출 구역 / 총 10개 구역':'소견과 다음 주 계획 작성',false,lead?'/ 10':'','file');
 else{const labels=role==='evangelist'?['담당 대상자',pro.length,'연락 필요',pro.filter(p=>p.lastContact< '2026-09-26').length]:role==='visitor'?['심방 기록',vis.length,'면담 대기',pending.length]:role==='educator'?['교육 과정',state.courses.length,'미응시',state.examResults.filter(e=>!e.attended).length]:role==='finance'?['이번 달 납부',state.contributions.length,'미납',ms.length-state.contributions.length]:['활동 계정',state.accounts.length,'권한 회수 대기',state.appointments.filter(a=>a.end&&!a.revoked).length];cards=stat(labels[0],labels[1],'허용 업무 영역 기준',true,'건')+stat(labels[2],labels[3],'확인이 필요합니다.',false,'건')+stat('내 담당 액션',state.actions.filter(a=>a.owner===role&&a.status==='진행').length,'기한과 상태를 확인하세요.',false,'건')+stat('접근 범위',role==='tf'?'기준정보':'지역 업무','메뉴별 업무 범위 적용');}
 const tasks=[['AT-01','출석 미입력 확인',`${metric.missing}명 · 이번 주 주일 예배`,'check'],['AT-03','장기결석 후속조치',`${abs.length}명 · 담당자 및 처리 단계 확인`,'users'],['VS-04','면담 요청 확인',`${pending.length}건 · 요청 대기`,'heart'],['WR-01','이번 주 주간보고 작성','수치는 자동으로, 소견만 작성','file'],['EV-05','연락이 필요한 대상자 확인','최근 접촉일 기준으로 확인','sprout'],['ED-05','미응시 회원 확인','시험 결과 입력 및 연락','book'],['FN-03','이번 달 미납 현황 확인','회계 전용 업무 영역','wallet'],['OR-04','임기 종료 권한 회수','수동 회수가 필요한 사명자','shield']].filter(t=>allowed(t[0]));
 const taskBody=tasks.slice(0,4).map(([id,title,desc,ic])=>`<a class="task" href="#${id}"><span class="task-icon">${icon(ic)}</span><div><strong>${title}</strong><small>${desc}</small></div><span style="margin-left:auto">${icon('arrow')}</span></a>`).join('');
 const compare=DISTRICTS.filter(d=>role!=='district'||d===district).map(d=>{const m=attendanceMetric(state,state.members.filter(m=>m.district===d),week,service);return `<div class="bar-row"><span>${d}</span><div class="bar-track"><div class="bar-fill" style="width:${m.rate}%"></div></div><strong>${m.rate}%</strong></div>`}).join('');
 const funnel=['찾기','정파','상담','복음방','센터','입교'].map(s=>`<div class="funnel-box"><small>${s}</small><strong>${pro.filter(p=>p.stage===s).length}</strong></div>`).join('');
 return scopeControls()+`<div class="stats">${cards}</div><div class="grid two">${panel('이번 주 필요한 조치',taskBody,'<span class="badge warn">확인 필요</span>','입력 누락과 조치 기한을 먼저 확인하세요.')}${allowed('AT-02')?panel('구역별 출석 현황',`<div class="district-bars">${compare}</div>`,link('출석 현황','AT-02'),'출석 + 온라인 / 활동 및 장기결석 회원'):panel('내 업무 접근 범위',notice(roles[role],screens.filter(s=>s.allow.includes(role)).map(s=>s.title).slice(0,8).join(' · '),true))}</div>${allowed('EV-01')?panel('전도 단계별 현황',`<div class="funnel">${funnel}</div>`,link('전체 보기','EV-01'),'현재 단계의 재적 인원 / 중단 제외'):''}<div class="grid equal">${allowed('WR-02')?panel('주간보고 제출 현황',reportRows(),link('보고 확인','WR-02')):panel('출석 주간 추이',chart(ms),allowed('AT-02')?link('추이 보기','AT-02'):'' )}${allowed('MT-02')?panel('회의 결정사항',actionList(),link('전체 보기','MT-02')):panel('설계 검토 안내',notice('시안 동작 범위','입력과 저장, 현황 갱신을 가상 데이터로 확인할 수 있습니다.',true))}</div>`}
function chart(ms){return `<div class="chart-space"><div class="chart">${[36,37,38,39,40,41].map(w=>{const m=attendanceMetric(state,ms,w,service);return `<div class="chart-col"><span>${m.rate}%</span><div class="chart-bar" style="height:${m.rate*1.2}px"></div><small>${w}주</small></div>`}).join('')}</div></div>`}
function actionList(){return state.actions.filter(a=>a.status==='진행'&&(role==='lead'||a.owner===role)).slice(0,4).map(a=>`<div class="task"><span class="task-icon">${icon('check')}</span><div><strong>${esc(a.title)}</strong><small>${roles[a.owner]} · ${a.deadline}</small></div>${badge(a.deadline<TODAY?'기한 경과':'진행')}</div>`).join('')||'<div class="empty">진행 중인 담당 결정사항이 없습니다.</div>'}
function memberList(){const filtered=members().filter(m=>(!statusFilter||m.status===statusFilter)&&(!search||m.name.includes(search)||label(state,m.id).includes(search)));const filters=`<div class="filter-row"><input id="member-search" placeholder="이름 또는 휴대전화 뒷 4자리 검색" aria-label="회원 검색" value="${esc(search)}">${select('member-status',[['','전체 상태'],'활동','장기결석','이명','제적','사고처리'],statusFilter,'aria-label="회원 상태" data-control="member-status"')}</div>`;return scopeControls()+filters+`<section class="panel">${table(['회원','소속 구역','상태','이번 주 출석','최근 심방','조치'],filtered.map(m=>[nameLink(m),esc(m.district),badge(m.status),badge(state.attendance.find(a=>a.memberId===m.id&&a.week===week&&a.service===service)?.status||'미입력'),state.visits.filter(v=>v.memberId===m.id).sort((a,b)=>b.date.localeCompare(a.date))[0]?.date||'-',link('카드 보기','MB-03')]))}<div class="table-footer"><span>조회 결과 ${filtered.length}명</span><span>전체 이름은 확인 사유를 남긴 개별 열람만 허용</span></div></section>${notice('회원 중심 통합 이력','회원 카드를 열면 출결, 심방, 교육, 사명, 구역 이동 기록이 연결됩니다.',true)}`}
function memberForm(){const m=location.hash.includes('?edit')?members().find(m=>m.id===memberId):null;return panel(m?'회원 정보 수정':'회원 기본 정보',form('member-form',`<input type="hidden" name="id" value="${m?.id||''}">${field('name','이름 *','text',m?.name||'','required maxlength="20"')}${field('phone','휴대전화 *','tel',m?.phone||'','required pattern="[0-9+() -]{8,20}"')}${sf('district','소속 구역 *',role==='district'?[district]:DISTRICTS,m?.district||district)}${sf('status','회원 상태',['활동','장기결석','이명','제적','사고처리'],m?.status||'활동')}${field('birthday','생년월일','date',m?.birthday||'')}${field('address','주소','text',m?.address||'')}${field('reason','변경 사유','textarea','')}<label class="checkline field full"><input name="consent" type="checkbox" ${m?.consent?'checked':''} required><span>개인정보 수집·이용 동의를 확인했습니다. 수집 목적과 보관기간의 확정·고지는 실제 운영 전에 필요합니다. 현재 입력은 가상 회원에 한합니다.</span></label>`,'회원 저장'))+notice('등록과 수정 이력 보존','사고처리 시 처리일을 자동 기록합니다. 회원 기록은 물리 삭제하지 않습니다.',true)}
