function attendance(){const ms=members().filter(m=>['활동','장기결석'].includes(m.status)),met=attendanceMetric(state,ms,week,service);return scopeControls()+`<div class="filter-row"><span>예배 유형</span>${select('service',state.settings.services,service,'aria-label="예배 유형" data-control="service"')}<span class="badge warn">미입력 ${met.missing}명</span>${btn('미입력만 출석으로','all-present')}</div>`+notice('미입력은 결석으로 처리하지 않습니다.','출석률은 (출석 + 온라인) / 활동·장기결석 회원으로 계산합니다. 사유결석의 분모 포함 여부는 운영 검토안입니다.',true)+`<form id="attendance-form"><section class="panel">${table(['회원','소속','출석 상태','결석 사유'],ms.map(m=>{const r=state.attendance.find(a=>a.memberId===m.id&&a.week===week&&a.service===service);return [nameLink(m),m.district,`<div class="segmented">${['출석','온라인','결석','사유결석'].map(s=>`<label><input type="radio" name="status-${m.id}" value="${s}" ${r?.status===s?'checked':''}><span>${s}</span></label>`).join('')}</div>`, `<input class="reason-input" name="reason-${m.id}" aria-label="${named(m.id)} 결석 사유" value="${esc(r?.reason||'')}" placeholder="사유 입력">`]}))}</section><div class="sticky-save"><span><strong>${ms.length}명</strong> · 같은 주차와 예배의 재입력은 갱신됩니다.</span><button class="btn primary" type="submit">출석 저장</button></div></form>`}
