 exams:['exams','시험 계획',[['name','시험명'],['courseId','교육 과정','select',state.courses.map(c=>[c.id,c.name])],['date','시행일','date'],['status','상태','select',['예정','완료','취소']]],['시험','과정','시행일','상태'],r=>[esc(r.name),esc(state.courses.find(c=>c.id===r.courseId)?.name),r.date,badge(r.status)]],
