function generic(type){const [key,title,fields,heads,toRow]=genericConfig(type);let list=state[key];if(['appointments','relationships','feedback'].includes(type))list=scoped(list);if(type==='feedback')list=list.filter(sensitive);if(type==='contacts')list=list.filter(r=>state.prospects.some(p=>p.id===r.prospectId&&visibleIds().has(p.guideId)));if(type==='meetings'&&role!=='lead')list=list.filter(m=>m.attendees?.includes(role));if(type==='actions'&&role!=='lead')list=list.filter(a=>a.owner===role);let writable=!(type==='meetings'&&role!=='lead');if(type==='actions'&&role!=='lead')writable=false;const formFields=fields.map(([name,l,t,opts])=>t==='select'?sf(name,l,opts,undefined,'required'):field(name,l,t||'text',t==='date'?TODAY:'',`${name==='end'?'':'required'} ${t==='number'?'min="1" max="100"':''}`)).join('');let notes='';if(type==='appointments')notes=notice('임기 종료와 권한 회수는 별도 처리','기획서 p.8의 자동 회수와 p.6/18의 수동 회수가 상충합니다. 본 시안은 수동 회수 대기 목록을 제공합니다.');if(type==='relationships')notes=notice('용어와 동의 기준 확정 필요','인교섬강전의 세부 항목 정의와 관계 인원 동의 기준은 운영 검토가 필요합니다. 미확정 상태는 저장하지 않습니다.');if(type==='feedback')notes=notice('민감 기록 열람 제한','작성자와 지역장/회장에게만 내용이 보입니다. 다른 담당자의 피드백은 목록에서도 제외합니다.',true);if(type==='contacts')notes=notice('최근 연락일 자동 반영','등록된 접촉 기록의 가장 최근 날짜를 대상자의 최근 접촉일로 반영합니다.',true);return notes+(writable?panel(title+' 등록',form('generic-form',formFields,'등록'),'',type==='actions'?'담당자와 완료 기한을 함께 지정하세요.':''): '')+panel(title+' 목록',table([...heads,'처리'],list.map(r=>[...toRow(r),(writable||type==='actions')?rowEdit(key,r.id,type==='actions'?'상태 변경':'수정'):'조회 전용']))) }
function prospectForm(){return panel('대상자 정보',form('prospect-form',field('name','이름 *','text','','required')+field('phone','연락처','tel','','pattern="[0-9+() -]{8,20}"')+sf('age','연령대',['20대','30대','40대','50대','60대 이상'])+sf('path','만난 경로',['지인 소개','모임','직장','기타'])+nf('guideId','담당 인도자 *')+nf('leaderId','인도자의 구역장 *')+field('note','비고','textarea'),'대상자 등록'))+notice('시작 단계: 찾기','인도자와 소속 구역장을 필수로 지정합니다. 단계 이동은 별도 이력으로 관리합니다.',true)}
function stage(){const p=state.prospects.find(p=>p.id===prospectId&&visibleIds().has(p.guideId))||state.prospects.find(p=>visibleIds().has(p.guideId));if(!p)return panel('단계 이동','<div class="empty">등록된 대상자가 없습니다.</div>');return `<div class="grid equal">${panel('단계 변경',form('stage-form',sf('prospectId','대상자 *',prospectOpts(),p.id)+sf('to','변경할 단계 *',['찾기','정파','상담','복음방','센터','입교','중단'],p.stage)+field('date','변경일 *','date',TODAY,'required')+field('reason','변경 사유 *','textarea','','required'),'단계 변경 저장'))}${panel('단계 이동 이력',timeline(state.stageHistory.filter(h=>h.prospectId===p.id).sort((a,b)=>a.date.localeCompare(b.date)),h=>`<strong>${h.from||'신규'} → ${h.to}</strong><br><span class="muted">${esc(h.reason)}</span>`),badge(p.stage))}</div>`}
function dropout(){const list=state.prospects.filter(p=>visibleIds().has(p.guideId));const cutoff=new Date(TODAY);cutoff.setDate(cutoff.getDate()-state.settings.contactDays);const stale=list.filter(p=>p.stage!=='중단'&&p.stage!=='입교'&&(!p.lastContact||p.lastContact<cutoff.toISOString().slice(0,10)));return `<div class="filter-row">${field('month','조회 월','month',month,'data-control="month"')}</div>`+notice('기획서의 방치 알림 연결','EV-05를 탈락사유 관리 화면으로 유지하면서 미접촉 대상 목록도 함께 제공합니다. 최근 연락 기준은 시안 14일입니다.')+panel('연락이 필요한 대상자',table(['대상자','현재 단계','최근 접촉','인도자','조치'],stale.map(p=>[named(p.id),badge(p.stage),p.lastContact,named(p.guideId),link('접촉 기록','EV-04')])))+panel('월별 중단 사유',table(['대상자','중단일','사유','담당'],list.filter(p=>p.stage==='중단').map(p=>[named(p.id),state.stageHistory.filter(h=>h.prospectId===p.id&&h.to==='중단').at(-1)?.date||p.enteredAt,esc(p.reason),named(p.guideId)]))) }
function evStats(){const ps=state.prospects.filter(p=>visibleIds().has(p.guideId));const ids=new Set(ps.map(p=>p.id));const h=state.stageHistory.filter(h=>ids.has(h.prospectId)&&h.date.startsWith(month));const sts=['찾기','정파','상담','복음방','센터','입교'];return `<div class="filter-row">${field('month','조회 월','month',month,'data-control="month"')}</div>`+notice('재적 인원과 이동 건수는 다릅니다.','현재 단계 재적과 선택 월의 전환 건수를 구분합니다. 전환율은 해당 월 이전 단계 유입 인원 대비 다음 단계 도달 인원인 검토안입니다.',true)+panel('현재 단계별 인원',`<div class="funnel">${sts.map(s=>`<div class="funnel-box"><small>${s}</small><strong>${ps.filter(p=>p.stage===s).length}</strong></div>`).join('')}</div>`)+panel('월별 단계 이동',table(['단계 구간','진입 인원(분모)','다음 단계 이동','전환율'],sts.slice(0,-1).map((s,i)=>{const from=new Set(h.filter(x=>x.to===s).map(x=>x.prospectId));const moved=new Set(h.filter(x=>x.to===sts[i+1]&&from.has(x.prospectId)).map(x=>x.prospectId));return [s+' → '+sts[i+1],from.size,moved.size,from.size?Math.round(moved.size/from.size*100)+'%':'산출 제외']}))) }
function evangelists(){return panel('2026년 인도자별 현황',table(['인도자','소속','전체 대상자','입교','중단'],members().filter(m=>state.prospects.some(p=>p.guideId===m.id)).map(m=>{const ps=state.prospects.filter(p=>p.guideId===m.id);return [named(m.id),m.district,ps.length,ps.filter(p=>p.stage==='입교').length,ps.filter(p=>p.stage==='중단').length]}))) }
function absence(){return scopeControls()+notice('주간 배치의 수동 시뮬레이션',`연속 결석 ${state.settings.absenceWeeks}주 이상 회원을 중복 없이 등재합니다. 미입력이나 사유결석은 연속 결석으로 세지 않습니다.`)+panel('등재 및 후속조치',table(['회원','연속 결석','담당자','현재 단계','처리'],scoped(state.cases).map(c=>[nameLink(state.members.find(m=>m.id===c.memberId)),streak(state.attendance,c.memberId,week,service)+'주',named(c.ownerId),badge(c.stage),btn('단계 관리','case-edit',false,`data-id="${c.id}"`)])),btn('자동 등재 실행','absence-batch',true))}
function visitForm(){return panel('심방 내용 및 후속조치',form('visit-form',nf('memberId','심방 대상 *')+nf('visitorId','심방자 *')+field('date','심방일 *','date',TODAY,'required')+sf('type','심방 유형',['전화','대면'])+field('content','심방 내용 *','textarea','','required')+field('action','후속조치','text')+field('deadline','조치 기한','date')+`<label class="checkline field full"><input type="checkbox" name="sensitive"><span>민감 상담 내용으로 제한합니다. 작성자와 지역장/회장만 열람합니다.</span></label>`,'심방 기록 저장'))}
function visits(){const list=scoped(state.visits);const absent=members().filter(m=>!list.some(v=>v.memberId===m.id&&v.date.startsWith(month)));return scopeControls()+`<div class="filter-row">${field('month','조회 월','month',month,'data-control="month"')}</div><div class="stats">${stat('심방 기록',list.filter(v=>v.date.startsWith(month)).length,'선택 월',true,'건')}${stat('미심방 회원',absent.length,'선택 월 기록 없음',false,'명')}${stat('후속조치 진행',list.filter(v=>v.status!=='완료').length,'완료 처리 필요',false,'건')}${stat('기한 경과',list.filter(v=>v.status!=='완료'&&v.deadline<TODAY).length,'미완료 건',false,'건')}</div>`+panel('심방 및 후속조치',table(['회원','최근 심방','내용','후속조치','기한','처리'],list.filter(v=>v.date.startsWith(month)).map(v=>[named(v.memberId),v.date,v.sensitive&&!sensitive(v)?badge('열람 제한'):esc(v.content),esc(v.action),v.deadline,v.status==='완료'?badge('완료'):btn('완료 처리','complete-visit',false,`data-id="${v.id}"`)])))+panel('미심방 회원',table(['회원','소속','조치'],absent.map(m=>[nameLink(m),m.district,link('심방 기록','VS-01')]))) }
function interviewRequest(){return panel('면담 요청',form('interview-form',nf('memberId','대상 회원 *')+sf('target','요청 대상',['지역장','회장'])+field('reason','요청 사유 *','textarea','','required'),'면담 요청 제출'))+panel('내 구역 요청 현황',table(['회원','요청일','대상','상태','일정'],scoped(state.interviews).map(i=>[named(i.memberId),i.requested,i.target,badge(i.status),i.date||'미확정']))) }
function interviews(){return panel('면담 접수 및 진행 현황',table(['회원','요청일','요청 대상','상태','일정','처리'],scoped(state.interviews).map(i=>[named(i.memberId),i.requested,i.target,badge(i.status),i.date||'미확정',role==='lead'?btn('배정 / 결과','interview-edit',false,`data-id="${i.id}"`):'상태 조회'])))+notice('결과는 민감 기록으로 제한','구역장은 접수와 일정 상태를 확인할 수 있습니다. 면담 내용은 작성자와 지역장/회장만 열람합니다.',true)}
function worship(){const d=district==='전체 구역'?'1구역':district;const w=state.worship.find(w=>w.district===d&&w.week===week);return scopeControls()+panel('구역예배 기록',form('worship-form',(role==='lead'?sf('district','입력 구역',DISTRICTS,d):'')+sf('conducted','진행 여부 *',[[true,'진행'],[false,'미진행']],w?.conducted??true)+field('date','진행 일자','date',w?.date||TODAY)+field('count','참석 인원','number',w?.count||'','min="0" max="1000"')+field('title','말씀 제목','text',w?.title||'')+field('note','특이사항 / 미진행 사유','textarea',w?.note||''),'구역예배 저장'))+notice('주간보고에 연결됩니다.','같은 구역·주차의 입력은 갱신됩니다. 미진행과 미입력을 구분합니다.',true)}
function courseAttendance(){const course=state.courses.find(c=>c.id===courseId)||state.courses[0];if(!course)return panel('교육 참석','교육 과정을 먼저 등록하세요.');courseId=course.id;return `<div class="filter-row">${select('course',state.courses.map(c=>[c.id,c.name]),courseId,'data-control="course" aria-label="교육 과정"')}${select('session',Array.from({length:course.sessions},(_,i)=>[i+1,(i+1)+'회차']),session,'data-control="session" aria-label="교육 회차"')}</div><form id="course-attendance-form">${panel('회차별 참석',table(['회원','참석 체크','누적 참석','이수율'],members().map(m=>{const n=state.courseAttendance.filter(a=>a.courseId===courseId&&a.memberId===m.id&&a.attended).length;return [named(m.id),`<label><input type="checkbox" name="attended-${m.id}" ${state.courseAttendance.find(a=>a.memberId===m.id&&a.courseId===courseId&&a.session===session)?.attended?'checked':''}> 참석</label>`,n+' / '+course.sessions+'회',Math.round(n/course.sessions*100)+'%']})))}<div class="form-actions"><button class="btn primary">참석 저장</button></div></form>`}
function examResults(){return `<div class="filter-row">${select('exam',state.exams.map(e=>[e.id,e.name]),examId,'data-control="exam" aria-label="시험"')}</div><form id="exam-results-form">${panel('응시와 점수',table(['회원','응시 여부','점수 (0~100)','상태'],members().map(m=>{const r=state.examResults.find(a=>a.examId===examId&&a.memberId===m.id);return [named(m.id),`<label><input type="checkbox" name="exam-${m.id}" ${r?.attended?'checked':''}> 응시</label>`,`<input class="reason-input" type="number" name="score-${m.id}" aria-label="${named(m.id)} 점수" min="0" max="100" value="${r?.score??''}">`,badge(r?.attended?'응시':'미응시')]})))}<div class="form-actions"><button class="btn primary">시험 결과 저장</button></div></form>`+notice('미응시는 0점과 다릅니다.','응시한 회원은 점수가 필수이고, 미응시 점수는 비워 둡니다.',true)}
function financeForm(){return notice('회계 전용 영역','가상 납부 데이터입니다. 실제 시스템은 finance 스키마와 별도 권한으로 저장해야 합니다.',true)+panel('납부 정보',form('finance-form',nf('memberId','회원 *')+sf('kind','납부 구분 *',['십일조','회비','서포터즈'],kind)+field('month','납부 연월 *','month',month,'required')+field('amount','금액 (원) *','number','','required min="1" max="100000000"')+field('date','납부일 *','date',TODAY,'required'),'납부 저장'))+panel('일괄 납부 등록',form('finance-bulk-form',sf('kind','구분',['십일조','회비','서포터즈'],kind)+field('month','연월','month',month,'required')+field('amount','공통 금액 (원)','number','10000','required min="1"')+`<div class="field full"><span>가상 회원 선택</span><div class="checkline">${members().slice(0,6).map(m=>`<label><input type="checkbox" name="bulk-${m.id}">${named(m.id)}</label>`).join('')}</div></div>`,'선택 회원 일괄 등록'))}
function finance(unpaid=false){const rows=state.contributions.filter(c=>c.month===month&&c.kind===kind);const paid=new Set(rows.map(r=>r.memberId)),ms=members().filter(m=>['활동','장기결석'].includes(m.status));return financeControls()+`<div class="stats">${stat('납부 합계',rows.reduce((a,c)=>a+c.amount,0).toLocaleString(),'선택 월 / 구분',true,'원','wallet')}${stat('납부 인원',paid.size,'기록 등록 기준',false,'명')}${stat('미납 인원',ms.filter(m=>!paid.has(m.id)).length,'활동·장기결석 회원 중',false,'명')}${stat('납부율',Math.round(paid.size/ms.length*100),'대상 회원 기준',false,'%')}</div>`+panel(unpaid?'미납 회원':'월별 납부 내역',unpaid?table(['회원','소속','연월','구분','상태'],ms.filter(m=>!paid.has(m.id)).map(m=>[named(m.id),m.district,month,kind,badge('미납')])):table(['회원','소속','구분','금액','납부일'],rows.map(r=>[named(r.memberId),esc(state.members.find(m=>m.id===r.memberId)?.district),r.kind,r.amount.toLocaleString()+'원',r.date])))+notice('조회 전용과 입력 권한 구분',role==='lead'?'지역장/회장은 회계 현황을 조회하며, 납부 등록은 회계 사명자만 수행합니다.':'회계 사명자 계정으로 납부를 관리합니다. 회원의 민감 상담 기록은 제공하지 않습니다.',true)}
function regionStats(){const reports=state.reports.filter(r=>r.week===week&&r.kind==='구역'&&r.status!=='작성중');return scopeControls()+notice('제출 당시 수치 기준','미제출 구역은 합계의 분모에서 제외합니다. 실시간 출석 현황과 제출 보고 수치가 다를 수 있습니다.',true)+`<div class="stats">${stat('제출 구역',reports.length,'전체 10개 구역',true,'/ 10')}${stat('제출 기준 출석률',reports.length?Math.round(reports.reduce((s,r)=>s+r.snapshot.present,0)/reports.reduce((s,r)=>s+r.snapshot.total,0)*100):'-','제출 구역 인원 가중 집계',false,'%')}${stat('심방 합계',reports.reduce((s,r)=>s+r.snapshot.visits,0),'제출 스냅샷 합계',false,'건')}${stat('면담 대기',reports.reduce((s,r)=>s+r.snapshot.pending,0),'제출 당시 기준',false,'건')}</div>`+panel('구역별 주간 비교',table(['구역','상태','출석률','장기결석','심방','면담대기'],DISTRICTS.map(d=>{const r=reports.find(r=>r.district===d);return [d,badge(r?.status||'미제출'),r?r.snapshot.rate+'%':'-',r?r.snapshot.absence:'-',r?r.snapshot.visits:'-',r?r.snapshot.pending:'-']}))) }
function move(){return panel('소속 변경',form('move-form',nf('memberId','대상 회원 *')+sf('type','이동 유형',['구역 이동','신규 편입','제적 / 사고처리'])+sf('to','이후 구역',DISTRICTS)+field('date','처리일 *','date',TODAY,'required')+field('reason','처리 사유 *','textarea','','required'),'이동 처리 저장'))+panel('이동 이력',table(['회원','이전 구역','이후 구역','일자','사유'],state.moves.map(x=>[named(x.memberId),esc(x.from||'외부'),esc(x.to||'사고처리'),x.date,esc(x.reason)]))) }
function weeks(){return notice('공통 주차 기준','일요일~토요일을 한 주로 사용합니다. 1월 1일을 포함하는 주가 1주차이며 ISO 주차와 다릅니다. 연말 중첩 처리 기준은 상세 설계 검토안입니다.',true)+panel('연도별 생성',form('weeks-form',field('year','기준 연도','number','2026','min="2020" max="2100" required'),'1년 주차 생성'))+panel('주차 목록',table(['주차 ID','연도','주차','시작일 (일)','종료일 (토)'],(state.weeks.length?state.weeks:Array.from({length:8},(_,i)=>({id:'2026'+(38+i),year:2026,number:38+i,...weekRange(2026,38+i)}))).map(w=>[w.id,w.year,w.number+'주',w.start,w.end]))) }
function permissions(){const heads=['역할','회원','전도','출결','심방','교육','회계','보고','회의','조직','시스템'];const gs=['MB','EV','AT','VS','ED','FN','WR','MT','OR','SY'];return notice('미확정 사항을 설정값으로 분리','장기결석 기준은 시안 8주, 미접촉은 시안 14일입니다. 회계 조회 범위와 민감 기록은 보수적으로 적용했습니다. 운영 확정 상태를 임의로 승인하지 않습니다.')+panel('역할별 메뉴 접근',table(heads,Object.entries(roles).map(([r,l])=>[l,...gs.map(g=>screens.some(s=>s.group===g&&s.allow.includes(r)&&s.id!=='FN-04')?badge(r==='lead'&&g==='FN'?'조회':'허용'):'-')])),'','화면 시안의 메뉴 허용 여부. 실제 운영은 역할 + 직책 + RLS의 교집합.')+panel('운영 기준 검토',form('settings-form',field('absenceWeeks','장기결석 기준 (주)','number',state.settings.absenceWeeks,'required min="1" max="52"')+field('contactDays','연락 필요 기준 (일)','number',state.settings.contactDays,'required min="1" max="365"')+field('services','예배 유형 (쉼표 구분)','text',state.settings.services.join(', '),'required')+field('retentionMonths','제적 후 보관기간 (개월) · 미확정','number',state.settings.retentionMonths??'','min="1" max="120"'),'시안 설정 저장'))}
function privacy(){return notice('파기 기준 확정 전에는 실행을 차단합니다.','보관기간, 익명화 방식, 동의문과 승인 절차가 미확정입니다. 현재 화면은 후보 검토 전용이며 실제 개인정보 삭제를 수행하지 않습니다.')+`<div class="stats">${stat('동의 확인',state.members.filter(m=>m.consent).length,'가상 회원',true,'명')}${stat('동의 미확인',state.members.filter(m=>!m.consent).length,'등록 확인 필요',false,'명')}${stat('보관기간',state.settings.retentionMonths??'미확정','운영 승인 필요',false,state.settings.retentionMonths?'개월':'')}${stat('파기 실행','잠금','기준 승인 전 검토만 허용')}</div>`+panel('사고처리 및 보존 후보',table(['회원','상태','처리일','동의','검토'],state.members.filter(m=>['제적','사고처리','이명'].includes(m.status)).map(m=>[named(m.id),badge(m.status),m.incidentAt||'-',badge(m.consent?'확인':'미확인'),badge('기준 확정 대기')])))+panel('보존·파기 방식 검토',`<div class="lockbox">${icon('lock')}<h3>실행 조건 미확정</h3><p class="muted">재적 중 보존 / 제적 후 기간 경과 시 식별정보 파기 / 비식별 통계 보존</p><button class="btn" disabled>익명화 실행 · 운영 기준 승인 필요</button></div>`)}
function auditView(){return panel('시안 조회 및 변경 이력',table(['일시','역할','작업','대상','사유'],state.audit.slice(0,30).map(a=>[new Date(a.at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}),roles[a.role],esc(a.action),esc(a.target),esc(a.reason)||'-'])))+notice('서버 감사 로그와 구분','시안 로그는 브라우저 저장소에만 기록되며 변경 방지 기능이 없습니다. 운영 서버에서 사용자 ID와 대상 ID를 기록해야 합니다.',true)}
function carry(){const expired=state.actions.filter(a=>a.deadline<TODAY&&a.status==='진행');return notice('원본 연결과 중복 이월 방지','기한이 지난 진행 항목만 다음 회의로 복제합니다. 완료·취소 항목은 제외하며, 같은 원본을 같은 회의에 다시 이월하지 않습니다.',true)+panel('다음 회의 선택',form('carry-form',sf('target','이월 대상 회의',state.meetings.map(m=>[m.id,m.title]),'mt2'),'미결 항목 이월'))+panel('기한 경과 미완료',table(['결정사항','원본 회의','담당자','기한','상태'],expired.map(a=>[esc(a.title),esc(state.meetings.find(m=>m.id===a.meetingId)?.title),roles[a.owner],a.deadline,badge('기한 경과')])))+panel('이월 연결 이력',table(['결정사항','원본 ID','대상 회의'],state.actions.filter(a=>a.originId).map(a=>[esc(a.title),esc(a.originId),esc(state.meetings.find(m=>m.id===a.meetingId)?.title)]))) }
function profile(){return panel('내 프로필',form('profile-form',field('name','표시 이름','text',label(state,'m1'),'readonly')+field('phone','가상 연락처','tel',state.profile.phone,'required')+field('email','계정 이메일','email',role+'@example.test','readonly')+field('role','역할','text',roles[role],'readonly'),'프로필 저장'))+panel('비밀번호 변경',notice('서버 인증 연동 필요','시안에서는 비밀번호를 수집하거나 저장하지 않습니다. 실제 서비스의 안전한 인증 흐름과 재설정 이메일을 연결해야 합니다.',true)) }
function view(s){switch(s.type){case'adminDashboard':return adminDashboard(state,{stat,panel,table,badge,link,icon,esc,named,roles});case'dashboard':return dashboard();case'profile':return profile();case'members':return memberList();case'memberForm':return memberForm();case'memberCard':return memberCard();case'memberMove':return move();case'attendance':return attendance();case'attendanceStats':return attendanceStats();case'absence':return absence();case'prospects':return prospectList();case'prospectForm':return prospectForm();case'stage':return stage();case'dropouts':return dropout();case'evStats':return evStats();case'evangelists':return evangelists();case'visitForm':return visitForm();case'visits':return visits();case'interviewRequest':return interviewRequest();case'interviews':return interviews();case'worship':return worship();case'courseAttendance':return courseAttendance();case'examResults':return examResults();case'financeForm':return financeForm();case'finance':return finance();case'unpaid':return finance(true);case'ownFinance':return notice('권한 확정 대기','p.6/18은 구역장 회계 접근 불가, p.14는 본인 또는 회원별 조회로 기술합니다. 승인 전까지 납부 데이터는 노출하지 않습니다.')+panel('회계 조회 권한',`<div class="lockbox">${icon('lock')}<h3>조회 범위를 먼저 확정해 주세요.</h3><p class="muted">본인 납부만 볼 수 있는지, 담당 회원 납부까지 볼 수 있는지 TF 결정이 필요합니다.</p><button class="btn" disabled>납부 내역 조회 · 권한 미확정</button></div>`);case'report':return report();case'reports':return scopeControls()+panel('구역별 제출 현황',reportRows());case'regionStats':return regionStats();case'weeks':return weeks();case'permissions':return permissions();case'privacy':return privacy();case'audit':return auditView();case'carry':return carry();default:return generic(s.type)}}
function setMenu(open,restore=false){const sidebar=$('.sidebar'),trigger=$('[data-action="menu"]');if(!sidebar)return;sidebar.classList.toggle('open',open);document.body.classList.toggle('menu-open',open);$('.menu-backdrop').hidden=!open;$('.main').inert=open;trigger.setAttribute('aria-expanded',String(open));if(open)$('.drawer-close').focus();else if(restore)trigger.focus()}
function render(){document.body.classList.remove('menu-open');route=location.hash.slice(1).split('?')[0]||'CM-02';if(role==='admin'&&route==='CM-02')route='AD-02';const s=byId[route]||byId['CM-02'];if(s.id==='AD-01'){ $('#app').innerHTML=adminLogin({field,icon,notice});$('#admin-login-form input[name="remember"]').checked=!!localStorage.getItem('sindorim-admin-email');document.title='관리자 로그인 | 신도림';return }if(s.id==='CM-01'){ $('#app').innerHTML=login();return }let body;if(!s.allow.includes(role))body=panel('접근 권한 확인',`<div class="lockbox">${icon('lock')}<h3>현재 역할에서 사용할 수 없는 화면입니다.</h3><p class="muted">시안 역할을 변경해 승인된 메뉴 범위를 검토하세요.</p>${link('내 업무로 이동','CM-02',true)}</div>`);else body=view(s);$('#app').innerHTML=shell(s,body);document.title=s.title+' | 신도림';if(s.type==='report'&&role==='district'){const r=state.reports.find(r=>r.district===district&&r.week===week&&r.status!=='작성중');if(r)$('#report-form button[type="submit"]').disabled=true}}
function modal(title,body){$('#modal').innerHTML=`<h2>${title}</h2>${body}`;$('#modal').showModal()}
function close(){ $('#modal').close() }
function serialized(form){return Object.fromEntries(new FormData(form).entries())}
function requiredMember(id){const m=members().find(m=>m.id===id);if(!m)throw Error('허용 범위의 회원을 선택하세요.');return m}
function requiredProspect(id){const p=state.prospects.find(p=>p.id===id&&visibleIds().has(p.guideId));if(!p)throw Error('허용 범위의 대상자를 선택하세요.');return p}
function submitReport(f,draft=false){const current=state.reports.find(r=>r.district===district&&r.week===week&&r.kind==='구역');if(current&&current.status!=='작성중')throw Error('제출된 보고는 수정할 수 없습니다.');const v=serialized(f);if(!draft&&!v.opinion.trim())throw Error('소견을 입력하세요.');const snapshot=reportSnapshot(state,members(),week,service);if(!draft&&(snapshot.missing||snapshot.worship===null)){modal('입력 누락이 있습니다.',`<p>출석 미입력 ${snapshot.missing}명${snapshot.worship===null?' · 구역예배 미입력':''}. 누락 상태를 포함해 제출하시겠습니까?</p>${btn('입력 확인','close')}${btn('누락 상태로 제출','force-report',true)}`);window.pendingReport={...v,snapshot};return}saveReport(v,draft,snapshot)}
function saveReport(v,draft,snapshot){upsert(state.reports,{...v,id:'r'+district+week,district,week,kind:'구역',status:draft?'작성중':'제출',snapshot:draft?null:structuredClone(snapshot),submittedAt:draft?null:new Date().toISOString()},['district','week','kind']);persist(draft?'보고 임시저장':'보고 제출',district+'/'+week)}
document.addEventListener('submit',e=>{e.preventDefault();try{const f=e.target,v=serialized(f),s=byId[route];if(!['login-form','admin-login-form'].includes(f.getAttribute('id'))&&!s?.allow.includes(role))throw Error('접근 권한이 없습니다.');const id=()=>crypto.randomUUID();switch(f.getAttribute('id')){
 case'admin-login-form':{const error=$('#admin-login-error');if(v.email!=='admin@example.test'||v.password!=='demo1234'){error.textContent='검토용 관리자 계정 정보를 확인하세요.';error.hidden=false;return}role='admin';district='전체 구역';sessionStorage.setItem('demo-role',role);if(v.remember)localStorage.setItem('sindorim-admin-email',v.email);else localStorage.removeItem('sindorim-admin-email');audit('관리자 시안 접속',role);goto('AD-02');render();return;}
 case'login-form':role=v.role;district=role==='district'?district==='전체 구역'?'1구역':district:'전체 구역';sessionStorage.setItem('demo-role',role);audit('시안 접속',role);goto(role==='admin'?'AD-02':'CM-02');render();return;
 case'member-form':if(role==='district')v.district=district;const existing=state.members.find(m=>m.id===v.id);const m={...v,id:v.id||id(),consent:!!v.consent,consentAt:existing?.consentAt||TODAY,createdAt:existing?.createdAt||TODAY,createdBy:existing?.createdBy||role,updatedAt:TODAY,updatedBy:role};if(['제적','사고처리'].includes(v.status))m.incidentAt=existing?.incidentAt||TODAY;upsert(state.members,m,['id']);memberId=m.id;persist('회원 저장',m.id);goto('MB-03');return;
 case'profile-form':state.profile.phone=v.phone;persist('내 정보 수정',role);return;
 case'attendance-form':for(const m of members()){const status=v['status-'+m.id];if(!status)continue;upsert(state.attendance,{memberId:m.id,week,service,status,reason:v['reason-'+m.id]||'',updatedAt:TODAY,updatedBy:role},['memberId','week','service'])}persist('출석 저장',week+'/'+service);return;
 case'prospect-form':requiredMember(v.guideId);const leader=requiredMember(v.leaderId);if(leader.district!==requiredMember(v.guideId).district)throw Error('인도자와 구역장의 소속 구역이 일치해야 합니다.');const p={...v,id:id(),stage:'찾기',enteredAt:TODAY,lastContact:null};state.prospects.push(p);state.stageHistory.push({id:id(),prospectId:p.id,from:null,to:'찾기',date:TODAY,reason:'신규 등록'});persist('대상자 등록',p.id);goto('EV-01');return;
 case'stage-form':const pr=requiredProspect(v.prospectId);if(v.to===pr.stage)throw Error('현재 단계와 다른 단계를 선택하세요.');if(v.date<pr.enteredAt)throw Error('현재 단계 진입일보다 이전으로 이동할 수 없습니다.');state.stageHistory.push({id:id(),prospectId:pr.id,from:pr.stage,to:v.to,date:v.date,reason:v.reason});pr.stage=v.to;pr.enteredAt=v.date;pr.reason=v.to==='중단'?v.reason:'';prospectId=pr.id;persist('단계 변경',pr.id);return;
 case'visit-form':requiredMember(v.memberId);state.visits.push({...v,id:id(),week,status:'진행',sensitive:!!v.sensitive,author:role,district});persist('심방 등록',v.memberId);goto('VS-02');return;
 case'interview-form':requiredMember(v.memberId);state.interviews.push({...v,id:id(),status:'요청',requested:TODAY,district});persist('면담 요청',v.memberId);return;
 case'worship-form':if(v.conducted==='true'&&(!v.date||!v.count||!v.title.trim()))throw Error('진행한 구역예배는 일자, 참석 인원과 말씀 제목을 입력하세요.');upsert(state.worship,{...v,id:id(),district:role==='district'?district:v.district,week,conducted:v.conducted==='true',count:Number(v.count)},['district','week']);persist('구역예배 저장',district+'/'+week);return;
 case'course-attendance-form':for(const m of members())upsert(state.courseAttendance,{memberId:m.id,courseId,session,attended:!!v['attended-'+m.id]},['memberId','courseId','session']);persist('교육 참석 저장',courseId+'/'+session);return;
 case'exam-results-form':for(const m of members()){if(v['exam-'+m.id]&&v['score-'+m.id]==='')throw Error('응시 회원의 점수를 입력하세요.')}for(const m of members())upsert(state.examResults,{memberId:m.id,examId,attended:!!v['exam-'+m.id],score:v['exam-'+m.id]?Number(v['score-'+m.id]):null},['memberId','examId']);persist('시험 결과 저장',examId);return;
 case'finance-form':if(!canWriteFinance())throw Error('회계 입력 권한이 없습니다.');requiredMember(v.memberId);upsert(state.contributions,{...v,id:id(),amount:Number(v.amount)},['memberId','kind','month']);persist('납부 등록',v.memberId);return;
 case'finance-bulk-form':if(!canWriteFinance())throw Error('회계 입력 권한이 없습니다.');const picked=members().filter(m=>v['bulk-'+m.id]);if(!picked.length)throw Error('일괄 등록할 회원을 선택하세요.');picked.forEach(m=>upsert(state.contributions,{id:id(),memberId:m.id,kind:v.kind,month:v.month,amount:Number(v.amount),date:TODAY},['memberId','kind','month']));persist('납부 일괄 등록',picked.length+'명');return;
 case'report-form':submitReport(f);return;
 case'functional-report':state.reports.push({...v,id:id(),kind:role,week,status:'제출',submittedAt:new Date().toISOString()});persist('기능 보고 제출',role+'/'+week);return;
 case'move-form':const mm=requiredMember(v.memberId);if(v.type==='구역 이동'&&mm.district===v.to)throw Error('다른 구역을 선택하세요.');state.moves.push({...v,id:id(),from:v.type==='신규 편입'?null:mm.district,to:v.type==='제적 / 사고처리'?null:v.to});if(v.type==='제적 / 사고처리'){mm.status='사고처리';mm.incidentAt=v.date}else{mm.district=v.to;mm.status='활동'}persist('구역 이동',mm.id);return;
 case'weeks-form':const year=Number(v.year),end=weekRange(year,1).start;state.weeks=state.weeks.filter(w=>w.year!==year);for(let n=1;n<=54;n++){const r=weekRange(year,n);if(r.start>year+'-12-31')break;state.weeks.push({id:year+String(n).padStart(2,'0'),year,number:n,...r})}persist('주차 일괄 생성',year);return;
 case'settings-form':state.settings={...state.settings,absenceWeeks:Number(v.absenceWeeks),contactDays:Number(v.contactDays),services:[...new Set(v.services.split(',').map(s=>s.trim()).filter(Boolean))],retentionMonths:v.retentionMonths?Number(v.retentionMonths):null,confirmed:false};persist('시안 운영 기준 저장','설정');return;
 case'carry-form':const count=carryActions(state,v.target,TODAY);audit('미결 이월',v.target,count+'건');save(state);render();toast(count+'건을 이월했습니다.');return;
 case'generic-form':{const [key,,fields]=genericConfig(s.type);if(s.type==='meetings'&&role!=='lead')throw Error('회의 등록 권한이 없습니다.');if(s.type==='relationships'&&v.consent!=='확인')throw Error('동의 확인 후 저장할 수 있습니다.');if(s.type==='accounts'&&state.accounts.some(a=>a.email===v.email||a.memberId===v.memberId))throw Error('동일 이메일 또는 회원의 계정이 이미 있습니다.');if(s.type==='courses'){v.sessions=Number(v.sessions);if(v.end<v.start)throw Error('종료일은 시작일 이후여야 합니다.')}const r={...v,id:id(),createdAt:TODAY,createdBy:role};if(key==='districts')r.id=v.name;if(['feedback'].includes(key)){r.author=role;r.district=district}if(key==='meetings'){r.attendees=['lead','district','evangelist','visitor','educator','finance']}if(key==='actions'&&r.status==='완료')r.completedAt=TODAY;state[key].push(r);if(key==='contacts'){const pp=requiredProspect(v.prospectId);if(!pp.lastContact||v.date>pp.lastContact)pp.lastContact=v.date}if(key==='meetings')carryActions(state,r.id,TODAY);persist('기록 등록',key);return;}
 case'edit-record-form':applyRecordEdit(v);return;
 case'case-form':{const c=scoped(state.cases).find(c=>c.id===v.id);if(!c)throw Error('대상 없음');Object.assign(c,v);if(['단계향상','사고처리'].includes(v.stage)){c.closedAt=TODAY;if(v.stage==='사고처리'){const m=requiredMember(c.memberId);m.status='사고처리';m.incidentAt=TODAY}}close();persist('조치 단계 수정',c.memberId);return;}
 case'interview-edit-form':if(role!=='lead')throw Error('면담 배정 권한이 없습니다.');const int=state.interviews.find(i=>i.id===v.id);if(v.status==='일정확정'&&!v.date)throw Error('면담 일정을 지정하세요.');if(v.status==='완료'&&!v.result.trim())throw Error('완료 결과를 입력하세요.');Object.assign(int,v,{author:role});close();persist('면담 처리',int.memberId);return;
 case'reveal-form':if(!v.reason.trim())throw Error('열람 사유를 입력하세요.');const target=requiredMember(v.id);audit('전체 이름 열람',target.id,v.reason);modal('개별 확인',`<p><strong>${esc(target.name)}</strong></p><p class="muted small-text">열람 사유와 시각을 기록했습니다. 이 창을 닫으면 다시 마스킹됩니다.</p>${btn('확인 후 닫기','close',true)}`);return;
 default:return;
 }}catch(err){toast(err.message)}});
function applyRecordEdit(v){const {collection,id}=v;const cfg=Object.keys(byId).map(k=>byId[k]).find(s=>genericConfig(s.type)?.[0]===collection&&s.allow.includes(role));if(!cfg)throw Error('변경 권한이 없습니다.');const r=state[collection].find(r=>r.id===id);if(!r)throw Error('기록 없음');if(collection==='actions'&&role!=='lead'&&r.owner!==role)throw Error('담당 액션만 변경할 수 있습니다.');if(collection==='meetings'&&role!=='lead')throw Error('회의 변경 권한이 없습니다.');if(collection==='feedback'&&!sensitive(r))throw Error('피드백 변경 권한이 없습니다.');if(collection==='accounts'&&r.role==='admin'&&r.status==='활동'&&(v.role!=='admin'||v.status!=='활동')&&state.accounts.filter(a=>a.role==='admin'&&a.status==='활동').length<=1)throw Error('마지막 활동 관리자 계정은 유지해야 합니다.');if(v.sessions)v.sessions=Number(v.sessions);if(collection==='courses'&&v.end<v.start)throw Error('교육 기간을 확인하세요.');if(collection==='accounts'&&state.accounts.some(a=>a.id!==id&&(a.email===v.email||a.memberId===v.memberId)))throw Error('중복 계정입니다.');if(collection==='districts'&&v.status==='비활성'&&state.members.some(m=>m.district===r.id&&['활동','장기결석'].includes(m.status)))throw Error('소속 활동 회원을 이동한 뒤 비활성 처리하세요.');if(collection==='relationships'&&v.consent!=='확인')throw Error('동의 확인이 필요합니다.');delete v.collection;Object.assign(r,v,{updatedAt:TODAY,updatedBy:role});if(collection==='actions'&&v.status==='완료')r.completedAt=TODAY;if(collection==='contacts'){const p=requiredProspect(r.prospectId);p.lastContact=state.contacts.filter(c=>c.prospectId===p.id).map(c=>c.date).sort().at(-1)||null}close();persist('기록 수정',collection+'/'+id)}
document.addEventListener('click',e=>{const m=e.target.closest('[data-member]');if(m){memberId=m.dataset.member;tab='기본정보';audit('회원 카드 조회',memberId);if(route==='MB-03')render()}const p=e.target.closest('[data-prospect]');if(p)prospectId=p.dataset.prospect;const a=e.target.closest('[data-action]');if(!a)return;try{const action=a.dataset.action;switch(action){case'toggle-admin-password':{const input=$('#admin-login-form input[name="password"]');const visible=input.type==='password';input.type=visible?'text':'password';a.textContent=visible?'비밀번호 숨기기':'비밀번호 보기';a.setAttribute('aria-pressed',String(visible));break;}case'logout':sessionStorage.removeItem('demo-role');role='district';district='1구역';break;case'menu':setMenu(!$('.sidebar').classList.contains('open'));break;case'menu-close':setMenu(false,true);break;case'close':close();break;case'help':modal('화면설계 시안 안내',`<p>기획서의 47개 화면과 추가 관리자 2개 화면을 가상 데이터로 검토하는 웹 구현입니다.</p><p>기록은 현재 브라우저에 저장됩니다. 역할 전환은 시연 기능이며 보안 인증이 아닙니다.</p><p>실제 서비스에는 서버 인증, PostgreSQL RLS, 회계 스키마 분리, 감사 로그, 배치 및 개인정보 운영 기준이 필요합니다.</p>${btn('가상 데이터 초기화','reset-data')}${btn('닫기','close',true)}`);break;case'catalog':e.preventDefault();modal(`${screens.length}개 화면 설계 목록`,`<p class="small-text muted">현재 역할에서 사용 가능한 화면만 이동할 수 있습니다.</p><div style="max-height:60vh;overflow:auto">${groups.map(([g,t])=>`<h3>${t}</h3>${screens.filter(s=>s.group===g).map(s=>`<p class="small-text">${s.id} &nbsp; ${allowed(s.id)?`<a href="#${s.id}" data-action="close">${s.title}</a>`:`${s.title} <span class="muted">· 역할 전환 필요</span>`}</p>`).join('')}`).join('')}</div>${btn('닫기','close')}`);break;case'reset-password':modal('비밀번호 재설정',`<p>실제 인증 서버 연결 전에는 메일을 발송하지 않습니다.</p><p class="muted">운영 화면: 이메일 입력 → 재설정 메일 → 새 비밀번호 설정</p>${btn('닫기','close',true)}`);break;case'reset-data':state=seed();save(state);close();render();toast('가상 데이터를 초기화했습니다.');break;case'member-tab':tab=a.dataset.tab;render();break;case'edit-member':memberId=a.dataset.id;goto('MB-02?edit');break;case'reveal':modal('전체 이름 개별 열람',form('reveal-form',`<input type="hidden" name="id" value="${a.dataset.id}">${field('reason','본인 확인이 필요한 사유 *','textarea','','required')}`,'이름 확인',btn('취소','close')));break;case'all-present':document.querySelectorAll('#attendance-form .segmented').forEach(g=>{if(!g.querySelector('input:checked'))g.querySelector('input[value="출석"]').checked=true});toast('미입력 회원을 출석으로 선택했습니다. 저장하면 반영됩니다.');break;case'draft-report':submitReport($('#report-form'),true);break;case'force-report':{const v=window.pendingReport;close();saveReport(v,false,v.snapshot);window.pendingReport=null;break;}case'confirm-report':{if(role!=='lead')throw Error('확인 권한이 없습니다.');const r=state.reports.find(r=>r.id===a.dataset.id);modal('제출 보고 확인',`<p>${esc(r.district)} · ${r.week}주차 · ${badge(r.status)}</p><div class="report-summary"><div><small>출석률</small><strong>${r.snapshot.rate}%</strong></div><div><small>장기결석</small><strong>${r.snapshot.absence}명</strong></div></div><h4>소견</h4><p>${esc(r.opinion)}</p><h4>특이사항</h4><p>${esc(r.note)}</p><h4>다음 주 계획</h4><p>${esc(r.plan)}</p>${r.status==='확인'?`<p class="muted small-text">확인 ${r.confirmedAt}</p>`:btn('확인 완료','mark-report',true,`data-id="${r.id}"`)}${btn('닫기','close')}`);break;}case'mark-report':if(role!=='lead')throw Error('확인 권한이 없습니다.');Object.assign(state.reports.find(r=>r.id===a.dataset.id),{status:'확인',confirmedBy:role,confirmedAt:new Date().toISOString()});close();persist('보고 확인',a.dataset.id);break;case'absence-batch':for(const m of members()){const n=streak(state.attendance,m.id,week,service);if(n>=state.settings.absenceWeeks&&!state.cases.some(c=>c.memberId===m.id&&!c.closedAt))state.cases.push({id:crypto.randomUUID(),memberId:m.id,weeks:n,ownerId:'',stage:'등재',result:''})}persist('장기결석 등재 시뮬레이션',week);break;case'case-edit':{const c=scoped(state.cases).find(c=>c.id===a.dataset.id);modal('담당자 및 처리 단계',form('case-form',`<input type="hidden" name="id" value="${c.id}">${sf('ownerId','담당자',[['','배정 대기'],...memberOpts()],c.ownerId)}${sf('stage','처리 단계',['등재','배정','접촉','심방','단계향상','사고처리'],c.stage)}${field('result','처리 결과','textarea',c.result)}`,'저장',btn('취소','close')));break;}case'complete-visit':{const v=scoped(state.visits).find(v=>v.id===a.dataset.id);if(!v)throw Error('허용 범위 밖입니다.');v.status='완료';v.completedAt=TODAY;persist('심방 후속조치 완료',v.id);break;}case'interview-edit':{const i=state.interviews.find(i=>i.id===a.dataset.id);modal('면담 배정과 결과',form('interview-edit-form',`<input type="hidden" name="id" value="${i.id}">${sf('assignee','면담자',['지역장','회장'],i.assignee)}${sf('status','처리 상태',['요청','배정','일정확정','완료','취소'],i.status)}${field('date','면담 일정','date',i.date||'')}${field('result','면담 결과 (민감)','textarea',i.result||'')}`,'처리 저장',btn('취소','close')));break;}case'edit-record':{const key=a.dataset.collection;const cfg=genericConfig(byId[route].type);const r=state[key].find(r=>r.id===a.dataset.id);let fields=cfg[2];if(key==='actions'&&role!=='lead')fields=fields.filter(f=>f[0]==='status');modal(cfg[1]+' 수정',form('edit-record-form',`<input type="hidden" name="collection" value="${key}"><input type="hidden" name="id" value="${r.id}">${fields.map(([n,l,t,opts])=>t==='select'?sf(n,l,opts,r[n],'required'):field(n,l,t||'text',r[n],`${n==='end'?'':'required'} ${t==='number'?'min="1" max="100"':''}`)).join('')}`,'변경 저장',btn('취소','close')));break;}case'revoke':state.appointments.find(a=>a.id===a.dataset.id).revoked=true;persist('직책 권한 수동 회수',a.dataset.id);break;case'download-members':download(members().filter(m=>!statusFilter||m.status===statusFilter).map(m=>[label(state,m.id),m.district,m.status]),['회원','구역','상태'],'회원목록');break;case'download-unpaid':if(!canViewFinance())throw Error('회계 조회 권한이 없습니다.');const paid=new Set(state.contributions.filter(c=>c.month===month&&c.kind===kind).map(c=>c.memberId));download(members().filter(m=>['활동','장기결석'].includes(m.status)&&!paid.has(m.id)).map(m=>[label(state,m.id),m.district,month,kind]),['회원','구역','연월','구분'],'미납현황');break;}}catch(err){toast(err.message)}});
function download(rows,heads,title){const url=URL.createObjectURL(workbook(heads,rows));const a=document.createElement('a');a.href=url;a.download=title+'_'+TODAY+'.xlsx';a.click();URL.revokeObjectURL(url);audit('마스킹 다운로드',title,rows.length+'건');toast('마스킹된 Excel 파일을 다운로드했습니다.');}
document.addEventListener('change',e=>{const c=e.target.dataset.control,v=e.target.value;switch(c){case'role':role=v;district=role==='district'?(sessionStorage.getItem('demo-district')||'1구역'):'전체 구역';sessionStorage.setItem('demo-role',v);tab='기본정보';goto('CM-02');break;case'district':district=v;memberId=state.members.find(m=>m.district===v)?.id;sessionStorage.setItem('demo-district',v);break;case'week':week=Number(v);break;case'service':service=v;break;case'scope':district=v;break;case'month':month=v;break;case'kind':kind=v;break;case'member-status':statusFilter=v;break;case'stage-filter':stageFilter=v;break;case'course':courseId=v;session=1;break;case'session':session=Number(v);break;case'exam':examId=v;break;case'prospect-search':search=v;break;default:return}render()});
document.addEventListener('input',e=>{if(e.target.id==='member-search'){search=e.target.value;const pos=e.target.selectionStart;render();$('#member-search').focus();$('#member-search').setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{if(!$('.sidebar.open'))return;if(e.key==='Escape'){e.preventDefault();setMenu(false,true)}if(e.key==='Tab'){const items=[...$('.sidebar').querySelectorAll('a[href],button:not(:disabled)')].filter(el=>el.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('resize',()=>{if(window.innerWidth>720&&$('.sidebar.open'))setMenu(false)});
window.addEventListener('hashchange',()=>{search='';statusFilter='활동';render();window.scrollTo(0,0)});
// Expose metadata and read-only state snapshots for automated local QA / wireframe export.
window.prototype={screens,roles,getState:()=>structuredClone(state),reset:()=>{state=seed();save(state);render()},navigate:(id,r)=>{if(r){role=r;district=role==='district'?'1구역':'전체 구역';sessionStorage.setItem('demo-role',r)}location.hash=id;render()},setMember:(id)=>{memberId=id;render()}};
render();



